import os
print("Current working directory:", os.getcwd())
print("\nContents of current dir:")
for item in sorted(os.listdir('.')):
    print(f"  {item}")

# Check if there's a repo subdirectory
if os.path.exists('repo'):
    print("\nContents of repo/:")
    for item in sorted(os.listdir('repo')):
        print(f"  {item}")
else:
    # Maybe we're already in the repo
    print("\nChecking if this IS the repo...")
    if os.path.exists('.git'):
        print("Yes, .git exists here")
    if os.path.exists('arrow'):
        print("arrow/ directory exists here - this is the repo root")
